// 1. Rule of Zero: No user-declared special members.
class Simple {
    // Compiler generates all 6 special members with correct semantics.
    std::string name;
};

// 2. User-declared ctor suppresses default ctor.
class NoDefaultCtor {
public:
    NoDefaultCtor(int) {}
    // No default ctor is generated. Copy/move/dtor are generated.
};

// 3. User-declared copy/dtor suppresses move.
class NoMove {
public:
    NoMove(const NoMove&) = default;
    // Move operations are NOT generated because of the user-declared copy ctor.
};

// 4. User-declared move suppresses copy.
class MoveOnly {
public:
    MoveOnly(MoveOnly&&) = default;
    // Copy operations are implicitly deleted because of the user-declared move ctor.
};
